// ============================================================================
// SELECT QUEUED BATCH
// Reads every row from the library sheet, keeps only rows that still need a
// sound (Status is "Queued" or blank), caps the run to a safe batch size, and
// builds the clamped ElevenLabs request body for each. Rows already marked Done
// or Failed are skipped, so the workflow is idempotent and safe to run on a
// schedule.
// ============================================================================

// ---- EDIT HERE: the only block most people change -------------------------
const BATCH_SIZE = 10;                 // max rows generated per run (controls cost)
const DEFAULT_PROMPT_INFLUENCE = 0.3;  // used when PromptInfluence is blank
// ElevenLabs sound-generation hard limits (do not change unless the API does)
const MIN_DURATION = 0.5;
const MAX_DURATION = 30;
// ---------------------------------------------------------------------------

const clamp = (n, lo, hi) => Math.min(hi, Math.max(lo, n));
const cell = (v) => String(v === undefined || v === null ? '' : v).trim();

const rows = $input.all();
const out = [];

for (let i = 0; i < rows.length; i++) {
  const r = rows[i].json;

  // Idempotency: only pick rows that are Queued or blank. Done/Failed are skipped.
  const status = cell(r.Status).toLowerCase();
  if (status !== '' && status !== 'queued') continue;

  // A row needs a Description (the sound-effect prompt) to be generated.
  const description = cell(r.Description);
  if (!description) continue;

  if (out.length >= BATCH_SIZE) break;

  // Duration: blank means let ElevenLabs auto-pick, so omit the field entirely.
  // Any value is clamped to the API's 0.5 to 30 second range.
  let duration = null;
  const rawDur = cell(r.DurationSeconds);
  if (rawDur !== '') {
    const d = Number(rawDur);
    if (Number.isFinite(d)) duration = clamp(d, MIN_DURATION, MAX_DURATION);
  }

  // Prompt influence: clamp 0 to 1, default when blank or invalid.
  let influence = DEFAULT_PROMPT_INFLUENCE;
  const rawInf = cell(r.PromptInfluence);
  if (rawInf !== '') {
    const p = Number(rawInf);
    if (Number.isFinite(p)) influence = clamp(p, 0, 1);
  }

  const body = { text: description, prompt_influence: influence };
  if (duration !== null) body.duration_seconds = duration;

  // Deterministic, filesystem-safe MP3 name: sfx_<row>_<slug>.mp3
  const slug = description.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 40) || 'sound';
  const filename = 'sfx_' + r.row_number + '_' + slug + '.mp3';

  out.push({
    json: { row_number: r.row_number, description, filename, body },
    pairedItem: { item: i },
  });
}

return out;

// ============================================================================
// SUMMARIZE RUN
// Runs once after the per-row work. Counts how many rows were generated versus
// failed this run and builds the Slack recap line. Either write-back node may
// not have executed (an all-success run never touches Mark Row Failed), so each
// reference is guarded.
// ============================================================================

let done = [];
let failed = [];
try { done = $('Mark Row Done').all(); } catch (e) { done = []; }
try { failed = $('Mark Row Failed').all(); } catch (e) { failed = []; }

const generated = done.length;
const failedCount = failed.length;
const total = generated + failedCount;

const NL = String.fromCharCode(10);
const recapText =
  ':headphones: SFX Library Builder run' + NL +
  'Generated ' + generated + ', failed ' + failedCount +
  ' (of ' + total + ' queued row' + (total === 1 ? '' : 's') + ').';

return [{ json: { generated, failed: failedCount, total, recapText } }];
